import pandas as pd

def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()

    # Build watermark map: device_id -> applied_event_ts
    watermark = dict(zip(target["device_id"], target["applied_event_ts"]))

    # Determine which events survive (strictly greater than device's watermark)
    def survives(row):
        dev = row["device_id"]
        ts = row["event_ts"]
        if dev not in watermark:
            return True
        wm = watermark[dev]
        if pd.isna(wm):
            return True
        return ts > wm

    if len(cdc) > 0:
        mask = cdc.apply(survives, axis=1)
        surviving = cdc[mask].copy()
    else:
        surviving = cdc.copy()

    # Among surviving events per device, pick latest by (event_ts, event_seq)
    if len(surviving) > 0:
        surviving = surviving.sort_values(
            by=["device_id", "event_ts", "event_seq"],
            ascending=[True, True, True]
        )
        winners = surviving.groupby("device_id", as_index=False).tail(1)
    else:
        winners = surviving

    # Build result: start with target_snapshot devices
    result_rows = []

    target_devices = set(target["device_id"].tolist())
    winner_devices = set(winners["device_id"].tolist()) if len(winners) > 0 else set()

    # Devices in target_snapshot
    for _, row in target.iterrows():
        dev = row["device_id"]
        if dev in winner_devices:
            win_row = winners[winners["device_id"] == dev].iloc[0]
            result_rows.append({
                "device_id": dev,
                "reading": win_row["reading"],
                "applied_event_ts": win_row["event_ts"]
            })
        else:
            result_rows.append({
                "device_id": dev,
                "reading": row["reading"],
                "applied_event_ts": row["applied_event_ts"]
            })

    # New devices (winners not in target_snapshot)
    new_devices = winner_devices - target_devices
    for dev in new_devices:
        win_row = winners[winners["device_id"] == dev].iloc[0]
        result_rows.append({
            "device_id": dev,
            "reading": win_row["reading"],
            "applied_event_ts": win_row["event_ts"]
        })

    new_snapshot = pd.DataFrame(result_rows, columns=["device_id", "reading", "applied_event_ts"])

    new_snapshot["device_id"] = new_snapshot["device_id"].astype("int64")
    new_snapshot["reading"] = new_snapshot["reading"].astype("float64")
    new_snapshot["applied_event_ts"] = pd.to_datetime(new_snapshot["applied_event_ts"]).astype("datetime64[us]")

    return {"new_snapshot": new_snapshot}
